import { cp, copyFile, readFile, rm, writeFile } from "node:fs/promises";
import { existsSync } from "node:fs";

const required = ["dist/index.html", "dist/assets"];
for (const path of required) {
  if (!existsSync(path)) {
    throw new Error(`Missing ${path}. Run the production build first.`);
  }
}

const marker =
  "<!-- Generated by npm run build:pages. Do not edit; edit dev.html and src instead. -->";

await rm("assets", { recursive: true, force: true });
await cp("dist/assets", "assets", { recursive: true });
await copyFile("dist/index.html", "index.html");

for (const file of ["favicon.svg", ".nojekyll", "config.json"]) {
  if (existsSync(`dist/${file}`)) {
    await copyFile(`dist/${file}`, file);
  }
}

if (existsSync("dist/data")) {
  await rm("data", { recursive: true, force: true });
  await cp("dist/data", "data", { recursive: true });
}

const html = await readFile("index.html", "utf8");
if (!html.startsWith(marker)) {
  await writeFile("index.html", `${marker}\n${html}`);
}

console.log("Published production build to repository root");
